function f(r,n,t=null){if(!r||typeof r!="object")return t;const o=n.split(".");let e=r;for(const s of o)if(e&&typeof e=="object"&&s in e)e=e[s];else return t;return e}function c(r,n,t=null){return!Array.isArray(r)||n<0||n>=r.length?t:r[n]}function i(r,n=0){try{if(r==null||r==="")return n;const t=Number(r);return isNaN(t)?n:t}catch(t){return console.error("数字转换错误:",t),n}}export{i as a,c as b,f as s};
